#!/usr/bin/env python3
import json
import re
import os
import sys

# 1. Read vocabBuilderData.ts to extract detailed lessons and roots
vocab_builder_path = os.path.join(os.getcwd(), 'src/data/vocabBuilderData.ts')
with open(vocab_builder_path, 'r', encoding='utf-8') as f:
    vocab_data_content = f.read()

# Extract valid roots
root_ids = set(re.findall(r"id:\s*'(root-[^']+)'", vocab_data_content))
print(f"Found {len(root_ids)} root IDs: {sorted(list(root_ids))}")

# Parse lesson blocks manually or via python regex
lesson_blocks = re.findall(r"\{\s*id:\s*'(lesson-\d+)'[\s\S]*?word:\s*'([^']+)'[\s\S]*?partOfSpeech:\s*'([^']+)'[\s\S]*?difficulty:\s*'([^']+)'[\s\S]*?shortGloss:\s*'([^']+)'", vocab_data_content)

preserved_lessons = []
preserved_headwords = set()

for lid, word, pos, diff, gloss in lesson_blocks:
    # search for rootId in lesson etymology
    r_match = re.search(r"id:\s*'" + lid + r"'[\s\S]*?rootId:\s*'(root-[^']+)'", vocab_data_content)
    root_id = r_match.group(1) if r_match else None
    
    topics = ['Rhetoric & Speech', 'Communication']
    w_lower = word.lower()
    if w_lower in ['egomaniac', 'ambivert', 'misanthrope', 'altruist']:
        topics = ['Psychology & Personality', 'Behavior']
    elif w_lower in ['dermatologist', 'neurologist', 'pathologist']:
        topics = ['Medicine & Science', 'Health']
    elif w_lower in ['pagan', 'cacophony', 'eulogy', 'monologue']:
        topics = ['Language & Culture', 'Rhetoric']
        
    preserved_lessons.append({
        'id': lid,
        'word': word,
        'partOfSpeech': pos,
        'definition': gloss,
        'difficulty': diff,
        'topicTags': topics,
        'rootId': root_id if root_id in root_ids else None,
        'hasDetailedLesson': True
    })
    preserved_headwords.add(w_lower)

print(f"Extracted {len(preserved_lessons)} preserved detailed lessons.")

# Extract derived words from root blocks
root_derived_sections = re.findall(r"id:\s*'(root-[^']+)'[\s\S]*?derivedWords:\s*\[([\s\S]*?)\]", vocab_data_content)
root_derived_items = []

for rid, section in root_derived_sections:
    words_in_sec = re.findall(r"word:\s*'([^']+)',\s*meaning:\s*'([^']+)'(?:,\s*pos:\s*'([^']+)')?", section)
    for w, m, pos in words_in_sec:
        w_clean = w.strip()
        if w_clean.lower() not in preserved_headwords:
            pos_val = pos if pos else ('noun' if w_clean.endswith('ist') or w_clean.endswith('ity') else ('adjective' if w_clean.endswith('ic') or w_clean.endswith('ous') or w_clean.endswith('al') else 'noun'))
            root_derived_items.append({
                'word': w_clean,
                'partOfSpeech': pos_val,
                'definition': m,
                'difficulty': 'Intermediate',
                'topicTags': ['Etymology', 'Word Families'],
                'rootId': rid if rid in root_ids else None,
                'hasDetailedLesson': False
            })

print(f"Extracted {len(root_derived_items)} root derived items.")

# Now let's assemble our master vocabulary catalog of 1,050+ entries
all_catalogue = []
seen = set()

# Add 36 detailed lessons first
for item in preserved_lessons:
    all_catalogue.append(item)
    seen.add(item['word'].lower())

# Add derived words from roots
for item in root_derived_items:
    w_lower = item['word'].lower()
    if w_lower not in seen:
        all_catalogue.append({
            'id': f"cat-{len(all_catalogue) + 1}",
            'word': item['word'],
            'partOfSpeech': item['partOfSpeech'],
            'definition': item['definition'],
            'difficulty': item['difficulty'],
            'topicTags': item['topicTags'],
            'rootId': item['rootId'],
            'hasDetailedLesson': False
        })
        seen.add(w_lower)

